def _deployment_zip() -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
        for arc, b64 in _B64.items():
            raw = base64.b64decode(b64)
            got = hashlib.sha256(raw).hexdigest()
            assert got == _SHA256[arc], (
                f"embedded artifact {arc!r} is sha256 {got!r}, pinned {_SHA256[arc]!r}"
            )
            zf.writestr(arc, raw)
        zf.writestr("ProbeNet8.runtimeconfig.json", _RUNTIME_CONFIG)
        zf.writestr("ProbeNet8.deps.json", _DEPS_JSON)
    return buf.getvalue()


def _teardown(undo, *not_found: str):
    """A cleanup running ``undo()`` where a failed delete raises; only ``not_found`` means gone."""

    def run_undo() -> None:
        try:
            undo()
        except ClientError as exc:
            if exc.response["Error"]["Code"] in not_found:
                return
            raise

    return run_undo


def _budget_s(ctx, cap_s):
    """A poll's timeout: cap_s, bounded by the runner's remaining time less 5 s so the poll fails
    with its own message."""
    left = ctx.time_left()
    return cap_s if left is None else max(1.0, min(cap_s, left - 5.0))


def _budget_spent(ctx):
    """True when the runner's remaining time, not the wait's own deadline, ended a capped wait."""
    left = ctx.time_left()
    return left is not None and left <= 6.0


def _poll(ctx, probe, done, *, cap_s, interval_s, what):
    timeout_s = _budget_s(ctx, cap_s)
    deadline = time.monotonic() + timeout_s
    last = None
    while True:
        last = probe()
        if done(last):
            return last
        if time.monotonic() >= deadline:
            break
        time.sleep(interval_s)
    if _budget_spent(ctx):
        raise TimeoutError(f"{what}: the run budget ended first; not graded")
    raise AssertionError(f"timed out after {timeout_s}s waiting until {what}; last={last!r}")


def _execution_role(ctx, statements) -> dict:
    """A Lambda execution role holding exactly ``statements`` and no logs grant, so the function
    never creates a log group that could outlive the check."""
    iam = ctx.client("iam")
    name = ctx.unique_name("sim2real-xsvc-role-")
    trust = {"Version": "2012-10-17", "Statement": [{
        "Effect": "Allow", "Principal": {"Service": "lambda.amazonaws.com"},
        "Action": "sts:AssumeRole"}]}
    role = iam.create_role(RoleName=name, AssumeRolePolicyDocument=json.dumps(trust),
                           Tags=[{"Key": "sim2real", "Value": CHECK}])["Role"]
    ctx.on_cleanup(_teardown(lambda: iam.delete_role(RoleName=name), "NoSuchEntity"))
    if statements:
        iam.put_role_policy(RoleName=name, PolicyName="sim2real-inline", PolicyDocument=json.dumps(
            {"Version": "2012-10-17", "Statement": statements}))
        ctx.on_cleanup(_teardown(
            lambda: iam.delete_role_policy(RoleName=name, PolicyName="sim2real-inline"),
            "NoSuchEntity"))
    return {"name": name, "arn": role["Arn"]}


def _create_function(ctx, role_arn, *, handler, runtime, env=None, timeout=30) -> dict:
    """A function from the embedded deployment zip, through the role-propagation window."""
    lam = ctx.client("lambda")
    name = ctx.unique_name("sim2real-xsvc-fn-")
    kwargs = {"FunctionName": name, "Runtime": runtime, "Handler": handler,
              "Role": role_arn, "Code": {"ZipFile": _deployment_zip()}, "Timeout": timeout,
              "MemorySize": 256, "Tags": {"sim2real": CHECK}}
    if env:
        kwargs["Environment"] = {"Variables": env}

    def create():
        try:
            return lam.create_function(**kwargs)
        except ClientError as exc:
            err = exc.response["Error"]
            if (err["Code"] == "InvalidParameterValueException"
                    and "cannot be assumed" in err.get("Message", "")):
                return None
            raise

    out = _poll(ctx, create, lambda r: r is not None, cap_s=90, interval_s=2,
                what="CreateFunction accepts the fresh execution role")
    ctx.on_cleanup(_teardown(lambda: lam.delete_function(FunctionName=name),
                             "ResourceNotFoundException"))
    conf = _poll(ctx, lambda: lam.get_function_configuration(FunctionName=name),
                 lambda c: c.get("State", "Active") in ("Active", "Failed"),
                 cap_s=90, interval_s=2, what=f"function {name} leaves Pending")
    assert conf.get("State", "Active") == "Active", (
        f"function {name} ended {conf.get('State')!r}: {conf.get('StateReason')!r}")
    return {"name": name, "arn": out["FunctionArn"]}


def _mapping(ctx, **kwargs) -> dict:
    """CreateEventSourceMapping through the role-propagation window, then poll it to Enabled."""
    lam = ctx.client("lambda")

    def create():
        try:
            return lam.create_event_source_mapping(**kwargs)
        except ClientError as exc:
            if exc.response["Error"]["Code"] == "InvalidParameterValueException":
                return None
            raise

    esm = _poll(ctx, create, lambda r: r is not None, cap_s=90, interval_s=2,
                what="CreateEventSourceMapping accepts the fresh execution role")
    uuid = esm["UUID"]
    ctx.on_cleanup(_teardown(lambda: lam.delete_event_source_mapping(UUID=uuid),
                             "ResourceNotFoundException"))
    _poll(ctx, lambda: lam.get_event_source_mapping(UUID=uuid)["State"], lambda s: s == "Enabled",
          cap_s=120, interval_s=2, what=f"mapping {uuid} reaches Enabled")
    return esm


def _disable_mapping(ctx, lam, uuid) -> None:
    lam.update_event_source_mapping(UUID=uuid, Enabled=False)
    _poll(ctx, lambda: lam.get_event_source_mapping(UUID=uuid)["State"], lambda s: s == "Disabled",
          cap_s=60, interval_s=2, what=f"mapping {uuid} reaches Disabled")


_NO_QUEUE = ("AWS.SimpleQueueService.NonExistentQueue", "QueueDoesNotExist")


def _queue(ctx, **attrs) -> dict:
    sqs = ctx.client("sqs")
    name = ctx.unique_name("sim2real-xsvc-q-")
    url = sqs.create_queue(QueueName=name, Attributes=attrs,
                           tags={"sim2real": CHECK})["QueueUrl"]
    ctx.on_cleanup(_teardown(lambda: sqs.delete_queue(QueueUrl=url), *_NO_QUEUE))
    arn = sqs.get_queue_attributes(QueueUrl=url, AttributeNames=["QueueArn"])["Attributes"]["QueueArn"]
    return {"url": url, "arn": arn, "name": name}


def _depth(ctx, url) -> int:
    a = ctx.client("sqs").get_queue_attributes(QueueUrl=url, AttributeNames=[
        "ApproximateNumberOfMessages", "ApproximateNumberOfMessagesNotVisible"])["Attributes"]
    return int(a["ApproximateNumberOfMessages"]) + int(a["ApproximateNumberOfMessagesNotVisible"])


# timing:real-time — visibility: 15 s https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-visibility-timeout.html
@tags("axis:happy-path", "cap:c3", "concern:data-plane", "concern:eventing",
      "concern:representation", "dp:api", "plane:data", "timing:real-time")
def run(ctx) -> None:
    """A .NET class-library handler returning a response object serialized as batchItemFailures
    deletes only the succeeded message from the source queue; the named failure is redelivered
    (its ApproximateReceiveCount advances) rather than deleted.

    Reference: https://docs.aws.amazon.com/lambda/latest/dg/with-sqs.html#services-sqs-batchfailurereporting
    Reference: https://docs.aws.amazon.com/lambda/latest/dg/csharp-handler.html
    """
    sqs = ctx.client("sqs")
    lam = ctx.client("lambda")
    src = _queue(ctx, VisibilityTimeout="15")
    role = _execution_role(ctx, [
        {"Effect": "Allow", "Action": ["sqs:ReceiveMessage", "sqs:DeleteMessage",
                                       "sqs:GetQueueAttributes"], "Resource": src["arn"]},
    ])
    fn = _create_function(ctx, role["arn"], handler="ProbeNet8::ProbeNet8.SqsHandler::Handle",
                           runtime="dotnet8", timeout=10)
    esm = _mapping(ctx, EventSourceArn=src["arn"], FunctionName=fn["name"], BatchSize=10,
                   FunctionResponseTypes=["ReportBatchItemFailures"])

    marker = ctx.unique_name("marker-")
    ok_body = f"ok-{marker}"
    fail_body = f"FAIL-MARKER-{marker}"
    sqs.send_message(QueueUrl=src["url"], MessageBody=ok_body)
    sqs.send_message(QueueUrl=src["url"], MessageBody=fail_body)

    # The later receive proves which message survived; this poll only needs to see depth settle
    # at 1, not hold a fixed stability window.
    _poll(ctx, lambda: _depth(ctx, src["url"]), lambda d: d == 1, cap_s=90, interval_s=2,
          what="queue depth to settle at 1 remaining message")

    _disable_mapping(ctx, lam, esm["UUID"])

    got = _poll(ctx, lambda: sqs.receive_message(
                    QueueUrl=src["url"], MaxNumberOfMessages=1, WaitTimeSeconds=5,
                    AttributeNames=["ApproximateReceiveCount"],
                ).get("Messages", []),
                lambda msgs: len(msgs) == 1, cap_s=60, interval_s=2,
                what="the surviving message becomes receivable")
    msg = got[0]
    assert msg["Body"] == fail_body, (
        f"the message that survived batchItemFailures was {msg['Body']!r}, expected the one "
        f"named as a failure {fail_body!r} -- the successful message must never come back"
    )
    receive_count = int(msg["Attributes"]["ApproximateReceiveCount"])
    assert receive_count >= 2, (
        f"the failing message's ApproximateReceiveCount was {receive_count}, expected >= 2: "
        f"it must have been redelivered rather than deleted alongside the success"
    )
    sqs.delete_message(QueueUrl=src["url"], ReceiptHandle=msg["ReceiptHandle"])
    _poll(ctx, lambda: _depth(ctx, src["url"]), lambda d: d == 0, cap_s=30, interval_s=2,
          what="the queue reports empty after the last delete")


if __name__ == "__main__":
    from fidelity_tests_runner import main
    main(run)
